import numpy as np
from scipy.integrate import quad
from scipy.optimize import brentq
def v(t):
    return np.array([np.cos(t)**2, np.sin(2*t), np.sin(t)])
def vp(t):
    return np.array([-np.sin(2*t), 2*np.cos(2*t), np.cos(t)])
def vpp(t):
    return np.array([-2*np.cos(2*t), -4*np.sin(2*t), -np.sin(t)])
def G(t):
    a=v(t); return a/np.linalg.norm(a)
def Gp(t):
    a=v(t); ap=vp(t); r=np.linalg.norm(a)
    return ap/r - a*np.dot(a,ap)/r**3
def speed(t): return np.linalg.norm(Gp(t))
L,err=quad(speed,0,2*np.pi,epsabs=1e-12,epsrel=1e-12,limit=500)
L,err, min(speed(t) for t in np.linspace(0,2*np.pi,10001)), max(speed(t) for t in np.linspace(0,2*np.pi,10001))

