def phip(t):
    return 2/(np.cos(t)**2+4*np.sin(t)**2)
A_n, e=quad(lambda t:(1-np.sin(t))*phip(t),0,np.pi,points=[np.pi/2],epsabs=1e-12)
A_n, e, A_n/np.pi, 2*np.pi-A_n

