html = f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Whirligig: rolling spherical seam on torus</title>
<style>
  html,body {{ margin:0; height:100%; overflow:hidden; background:#101820; color:#eef3f7; font:14px system-ui,sans-serif; }}
  #view {{ width:100%; height:100%; display:block; }}
  #panel {{ position:absolute; top:14px; left:14px; z-index:2; width:min(330px,calc(100vw - 44px)); padding:14px 16px; border:1px solid #64717d; border-radius:10px; background:#17232ddd; backdrop-filter:blur(8px); }}
  h1 {{ font-size:16px; margin:0 0 10px; }}
  .line {{ display:flex; justify-content:space-between; gap:12px; margin:8px 0; }}
  input[type=range] {{ width:100%; }}
  button {{ border:1px solid #82909c; background:#263746; color:white; border-radius:6px; padding:7px 11px; cursor:pointer; }}
  button:hover {{ background:#354b5e; }}
  .small {{ color:#b9c7d1; font-size:12px; line-height:1.4; }}
  #readout {{ font-variant-numeric:tabular-nums; color:#d8e5ef; }}
</style>
<script type="importmap">
{{"imports":{{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js"}}}}
</script>
</head>
<body>
<div id="panel">
  <h1>Rolling sphere / torus seam model</h1>
  <div class="line"><button id="play">Pause</button><button id="reset">Reset</button><button id="home">Home view</button></div>
  <div class="line"><label for="speed">Speed</label><span id="speedval">1.0×</span></div>
  <input id="speed" type="range" min="0.1" max="3" step="0.1" value="1">
  <div class="line"><label for="progress">Orbit position</label><span id="progressval">0%</span></div>
  <input id="progress" type="range" min="0" max="1" step="0.001" value="0">
  <div class="line"><label><input id="showtrack" type="checkbox" checked> Inner track</label><label><input id="showaxes" type="checkbox" checked> Axes/grid</label></div>
  <div id="readout" class="small"></div>
  <p class="small">Model assumption: the sphere center follows the torus centerline. The ball rolls without slip, so its spin angle is distance travelled divided by sphere radius. The seam is painted on the sphere and rotates with it.</p>
  <p class="small">This is a kinematic visualization, not a collision-tested rigid-body simulation. Equal sphere and tube radii may cause geometric interference away from the instantaneous contact point.</p>
</div>
<canvas id="view"></canvas>
<script type="module">
import * as THREE from 'three';

const R = {R:.15f}, r = 1.0, b = {b};
const curve = {curve_json};
const canvas = document.querySelector('#view');
const renderer = new THREE.WebGLRenderer({{canvas, antialias:true}});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled = true;
renderer.setClearColor(0x101820);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x101820);
const camera = new THREE.PerspectiveCamera(42,innerWidth/innerHeight,0.1,100);
camera.up.set(0,0,1);
const homePos = new THREE.Vector3(10,-13,9);
camera.position.copy(homePos);
camera.lookAt(0,0,0);

scene.add(new THREE.HemisphereLight(0xeaf4ff,0x273442,2.0));
const key = new THREE.DirectionalLight(0xffffff,2.0);
key.position.set(4,-5,9); scene.add(key);

const torusMat = new THREE.MeshStandardMaterial({{color:0x7eabc8, transparent:true, opacity:0.24, roughness:0.55, metalness:0.08, side:THREE.DoubleSide}});
const torus = new THREE.Mesh(new THREE.TorusGeometry(R,r,48,240),torusMat);
scene.add(torus);

const ballGroup = new THREE.Group();
scene.add(ballGroup);
const ball = new THREE.Mesh(new THREE.SphereGeometry(r,64,48),new THREE.MeshStandardMaterial({{color:0xe7c879, transparent:true, opacity:0.66, roughness:0.72}}));
ballGroup.add(ball);

const seamPoints = curve.map(p=>new THREE.Vector3(p[0],p[1],p[2]));
seamPoints.push(seamPoints[0].clone());
const seamGeom = new THREE.BufferGeometry().setFromPoints(seamPoints);
const seam = new THREE.Line(seamGeom,new THREE.LineBasicMaterial({{color:0xff4057, linewidth:2}}));
ballGroup.add(seam);

const trackPts=[];
for(let i=0;i<=500;i++){{const q=2*Math.PI*i/500;trackPts.push(new THREE.Vector3((R-r)*Math.cos(q),(R-r)*Math.sin(q),0));}}
const track = new THREE.Line(new THREE.BufferGeometry().setFromPoints(trackPts),new THREE.LineBasicMaterial({{color:0x44d18b}}));
scene.add(track);

const centerlinePts=[];
for(let i=0;i<=500;i++){{const q=2*Math.PI*i/500;centerlinePts.push(new THREE.Vector3(R*Math.cos(q),R*Math.sin(q),0));}}
const centerline = new THREE.Line(new THREE.BufferGeometry().setFromPoints(centerlinePts),new THREE.LineDashedMaterial({{color:0xaab7c4,dashSize:0.12,gapSize:0.10}}));
centerline.computeLineDistances(); scene.add(centerline);

const axes = new THREE.AxesHelper(5);
scene.add(axes);
const grid = new THREE.GridHelper(12,24,0x506070,0x354554);
grid.rotation.x=Math.PI/2; grid.position.z=-1.02; scene.add(grid);

const contact = new THREE.Mesh(new THREE.SphereGeometry(0.055,16,12),new THREE.MeshBasicMaterial({{color:0xffffff}}));
scene.add(contact);

let playing=true, progress=0, speed=1;
const playBtn=document.querySelector('#play');
const progressEl=document.querySelector('#progress');
function setProgress(p){{
  progress=Math.max(0,Math.min(1,p));
  const phi=2*Math.PI*progress;
  // Sphere center moves on the torus centerline.
  ballGroup.position.set(R*Math.cos(phi),R*Math.sin(phi),0);
  // No-slip rolling: spin angle = traveled arc length / r = R*phi/r.
  // Initial W contact is at the inward (-x) point with +y tangent.
  ballGroup.rotation.set(0,0,(R/r)*phi);
  const er=new THREE.Vector3(Math.cos(phi),Math.sin(phi),0);
  contact.position.copy(ballGroup.position).addScaledVector(er,-r);
  progressEl.value=progress;
  document.querySelector('#progressval').textContent=(100*progress).toFixed(1)+'%';
  document.querySelector('#readout').innerHTML=
    `Center: (${{(R*Math.cos(phi)).toFixed(3)}}, ${{(R*Math.sin(phi)).toFixed(3)}}, 0)<br>`+
    `Spin: ${{((R/r)*phi).toFixed(3)}} rad &nbsp; | &nbsp; Orbit: ${{(phi*180/Math.PI).toFixed(1)}}°`;
}}
playBtn.onclick=()=>{{playing=!playing;playBtn.textContent=playing?'Pause':'Play';}};
document.querySelector('#reset').onclick=()=>{{playing=false;playBtn.textContent='Play';setProgress(0);}};
document.querySelector('#home').onclick=()=>{{camera.position.copy(homePos);camera.lookAt(0,0,0);}};
document.querySelector('#speed').oninput=e=>{{speed=+e.target.value;document.querySelector('#speedval').textContent=speed.toFixed(1)+'×';}};
progressEl.oninput=e=>{{playing=false;playBtn.textContent='Play';setProgress(+e.target.value);}};
document.querySelector('#showtrack').onchange=e=>{{track.visible=e.target.checked;}};
document.querySelector('#showaxes').onchange=e=>{{axes.visible=e.target.checked;grid.visible=e.target.checked;centerline.visible=e.target.checked;}};

let last=performance.now();
function animate(now){{
  requestAnimationFrame(animate);
  const dt=Math.min((now-last)/1000,0.05); last=now;
  if(playing){{setProgress((progress+dt*0.055*speed)%1);}}
  renderer.render(scene,camera);
}}
requestAnimationFrame(animate);
window.addEventListener('resize',()=>{{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}});
</script>
</body>
</html>'''
