# Build the updated dynamic model, preserving the dual-curve orientation constraint.
import os, json, numpy as np, matplotlib.pyplot as plt

# Pbody, Vbody, N, R, L, r are retained from the previous verified construction.
assert 'Pbody' in globals() and 'Vbody' in globals() and 'R' in globals()

pdat=json.dumps(np.round(Pbody,9).tolist(),separators=(',',':'))
tdat=json.dumps(np.round(Vbody,9).tolist(),separators=(',',':'))
html_crossbar = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Whirligig: tangent constraint, crossbar and pointer</title>
<style>
html,body{{margin:0;height:100%;overflow:hidden;background:#101820;color:#eef3f7;font:14px system-ui,sans-serif}}
#view{{width:100%;height:100%;display:block}}
#panel{{position:absolute;top:14px;left:14px;z-index:2;width:min(390px,calc(100vw - 44px));padding:14px 16px;border:1px solid #64717d;border-radius:10px;background:#17232ddd;backdrop-filter:blur(8px)}}
h1{{font-size:16px;margin:0 0 10px}}.line{{display:flex;justify-content:space-between;gap:12px;margin:8px 0}}
input[type=range]{{width:100%}}button{{border:1px solid #82909c;background:#263746;color:white;border-radius:6px;padding:7px 11px;cursor:pointer}}
.small{{color:#b9c7d1;font-size:12px;line-height:1.4}}#readout{{font-variant-numeric:tabular-nums;color:#d8e5ef}}
</style>
<script type="importmap">{{"imports":{{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js"}}}}</script>
</head><body>
<div id="panel">
<h1>Whirligig: crossbar and pointer arm</h1>
<div class="line"><button id="play">Pause</button><button id="reset">Reset</button><button id="home">Home view</button></div>
<div class="line"><label>Speed</label><span id="speedval">1.0×</span></div><input id="speed" type="range" min="0.1" max="3" step="0.1" value="1">
<div class="line"><label>Progress along petal / torus</label><span id="progressval">0%</span></div><input id="progress" type="range" min="0" max="1" step="0.001" value="0">
<div class="line"><label><input id="trackToggle" type="checkbox" checked> Inner circumference</label><label><input id="vectorsToggle" type="checkbox" checked> Tangent vectors</label></div>
<div class="line"><label><input id="barToggle" type="checkbox" checked> Crossbar</label><label><input id="pointerToggle" type="checkbox" checked> Pointer arm</label></div>
<div id="readout" class="small"></div>
<p class="small">Crossbar: sphere-local N–S diameter. Pointer: pivots at the crossbar midpoint, stays perpendicular to the crossbar, and makes one full relative revolution per complete petal-curve traversal.</p>
<p class="small">The moving petal anchor and shared tangent still determine the sphere orientation. The pointer's one-turn rotation is an additional driven motion about the sphere's N–S axis.</p>
</div>
<canvas id="view"></canvas>
<script type="module">
import * as THREE from 'three';
const R={R:.15f}, r=1, L={L:.15f}, N={N};
const P={pdat}, T={tdat};
const renderer=new THREE.WebGLRenderer({{canvas:document.querySelector('#view'),antialias:true}});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x101820);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);camera.up.set(0,0,1);
const home=new THREE.Vector3(9,-12,8);camera.position.copy(home);camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0xeaf4ff,0x273442,2));
const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(4,-5,9);scene.add(light);

const torus=new THREE.Mesh(new THREE.TorusGeometry(R,r,56,280),new THREE.MeshStandardMaterial({{color:0x7eabc8,transparent:true,opacity:.20,roughness:.6,side:THREE.DoubleSide}}));scene.add(torus);
const ballGroup=new THREE.Group();scene.add(ballGroup);
ballGroup.add(new THREE.Mesh(new THREE.SphereGeometry(r,72,56),new THREE.MeshStandardMaterial({{color:0xe7c879,transparent:true,opacity:.72,roughness:.7}}));
const seamPts=P.map(p=>new THREE.Vector3(...p));seamPts.push(seamPts[0].clone());
ballGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(seamPts),new THREE.LineBasicMaterial({{color:0xff4057}})));

// Crossbar passes through the sphere's N-S axis (local z) and extends slightly beyond it.
const metal=new THREE.MeshStandardMaterial({{color:0xd4dde5,metalness:.72,roughness:.28}});
const crossbar=new THREE.Mesh(new THREE.CylinderGeometry(.045,.045,2.28,24),metal);
crossbar.rotation.x=Math.PI/2; // cylinder's y-axis -> local z-axis
ballGroup.add(crossbar);

// Pointer pivot is at the crossbar midpoint. Its local z-axis is the crossbar axis.
// The arm begins at the midpoint and extends along local +x, remaining perpendicular.
const pointerPivot=new THREE.Group();ballGroup.add(pointerPivot);
const hub=new THREE.Mesh(new THREE.SphereGeometry(.105,24,18),new THREE.MeshStandardMaterial({{color:0xf1a340,metalness:.5,roughness:.35}}));
pointerPivot.add(hub);
const pointer=new THREE.Mesh(new THREE.CylinderGeometry(.035,.055,1.75,20),new THREE.MeshStandardMaterial({{color:0xf3a33a,metalness:.55,roughness:.32}}));
pointer.rotation.z=-Math.PI/2; // cylinder y-axis -> local +x
pointer.position.x=.875;
pointerPivot.add(pointer);
const tip=new THREE.Mesh(new THREE.SphereGeometry(.065,18,14),new THREE.MeshStandardMaterial({{color:0xffd27a,metalness:.4,roughness:.3}}));
tip.position.x=1.75;pointerPivot.add(tip);

// Circumference and torus centerline references.
function ring(rad,color,dashed=false){{
 const arr=[];for(let i=0;i<=700;i++){{const q=2*Math.PI*i/700;arr.push(new THREE.Vector3(rad*Math.cos(q),rad*Math.sin(q),0));}}
 const mat=dashed?new THREE.LineDashedMaterial({{color,dashSize:.12,gapSize:.1}}):new THREE.LineBasicMaterial({{color}});
 const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(arr),mat);if(dashed)line.computeLineDistances();scene.add(line);return line;
}}
const innerTrack=ring(R-r,0x44d18b),centerline=ring(R,0xaab7c4,true);
const axes=new THREE.AxesHelper(5);scene.add(axes);
const grid=new THREE.GridHelper(12,24,0x506070,0x354554);grid.rotation.x=Math.PI/2;grid.position.z=-1.02;scene.add(grid);
const anchorDot=new THREE.Mesh(new THREE.SphereGeometry(.065,20,16),new THREE.MeshBasicMaterial({{color:0xffffff}}));scene.add(anchorDot);
const torusArrow=new THREE.ArrowHelper(new THREE.Vector3(0,1,0),new THREE.Vector3(R-r,0,0),.78,0x44d18b,.18,.11);scene.add(torusArrow);
const petalArrow=new THREE.ArrowHelper(new THREE.Vector3(0,1,0),new THREE.Vector3(R-r,0,0),.78,0xff4057,.13,.075);scene.add(petalArrow);

const v3=a=>new THREE.Vector3(a[0],a[1],a[2]);
function sample(arr,u){{
 const x=u*N,i=Math.min(N-1,Math.floor(x)),f=x-i;
 return v3(arr[i]).lerp(v3(arr[i+1]),f).normalize();
}}
let playing=true,progress=0,speed=1;
const progressEl=document.querySelector('#progress'),playBtn=document.querySelector('#play');
function setProgress(q){{
 progress=Math.max(0,Math.min(1,q));
 const phi=2*Math.PI*progress;
 const p=sample(P,progress);
 let t=sample(T,progress);t.addScaledVector(p,-t.dot(p)).normalize();
 const n=new THREE.Vector3().crossVectors(p,t).normalize();
 const er=new THREE.Vector3(Math.cos(phi),Math.sin(phi),0);
 const et=new THREE.Vector3(-Math.sin(phi),Math.cos(phi),0);
 const ez=new THREE.Vector3(0,0,1);
 const B=new THREE.Matrix4().makeBasis(p,t,n);
 const D=new THREE.Matrix4().makeBasis(er.clone().negate(),et,ez.clone().negate());
 const rot=D.multiply(B.invert());
 ballGroup.position.set(R*er.x,R*er.y,0);
 ballGroup.quaternion.setFromRotationMatrix(rot);

 // One pointer revolution per whole petal-curve/torus circuit.
 const pointerAngle=2*Math.PI*progress;
 pointerPivot.rotation.set(0,0,pointerAngle);

 const A=new THREE.Vector3().copy(ballGroup.position).addScaledVector(er,-r);
 anchorDot.position.copy(A);
 torusArrow.position.copy(A);torusArrow.setDirection(et);
 petalArrow.position.copy(A);petalArrow.setDirection(et);
 progressEl.value=progress;document.querySelector('#progressval').textContent=(100*progress).toFixed(1)+'%';
 document.querySelector('#readout').innerHTML=
 `Sphere origin radius: R = ${{R.toFixed(6)}}r<br>`+
 `Crossbar axis: sphere N–S axis<br>`+
 `Pointer rotation: ${{(pointerAngle*180/Math.PI).toFixed(1)}}° / 360°<br>`+
 `Petal / torus arc progress: ${{(100*progress).toFixed(1)}}% / ${{(100*progress).toFixed(1)}}%<br>`+
 `Shared tangent: (${{et.x.toFixed(3)}}, ${{et.y.toFixed(3)}}, 0)`;
}}
playBtn.onclick=()=>{{playing=!playing;playBtn.textContent=playing?'Pause':'Play';}};
document.querySelector('#reset').onclick=()=>{{playing=false;playBtn.textContent='Play';setProgress(0);}};
document.querySelector('#home').onclick=()=>{{camera.position.copy(home);camera.lookAt(0,0,0);}};
document.querySelector('#speed').oninput=e=>{{speed=+e.target.value;document.querySelector('#speedval').textContent=speed.toFixed(1)+'×';}};
progressEl.oninput=e=>{{playing=false;playBtn.textContent='Play';setProgress(+e.target.value);}};
document.querySelector('#trackToggle').onchange=e=>{{innerTrack.visible=e.target.checked;}};
document.querySelector('#vectorsToggle').onchange=e=>{{torusArrow.visible=e.target.checked;petalArrow.visible=e.target.checked;}};
document.querySelector('#barToggle').onchange=e=>{{crossbar.visible=e.target.checked;}};
document.querySelector('#pointerToggle').onchange=e=>{{pointerPivot.visible=e.target.checked;}};
let last=performance.now();function animate(now){{requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;if(playing)setProgress((progress+dt*.045*speed)%1);renderer.render(scene,camera);}}
setProgress(0);requestAnimationFrame(animate);
window.addEventListener('resize',()=>{{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}});
</script></body></html>'''
html_path='/mnt/data/whirligig_crossbar_pointer_demo.html'
with open(html_path,'w',encoding='utf-8') as f: f.write(html)
print("Wrote", html_path, os.path.getsize(html_path), "bytes")

